# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
        except tomllib.TOMLDecodeError as e:
            raise ConfigError(f'TOML decoding error: {e}')

    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config_value = _coerce_value(value, defaults.get(env_key))
            config[env_key] = config_value

    return config

def _coerce_value(value, default):
    if default is None:
        raise ConfigError(f'No default for environment variable {value}')

    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for environment variable {value}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_load_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_load_toml():
    defaults = {'key': 'value'}
    toml_content = b'key = "new_value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'key': 'new_value'}
    os.remove('config.toml')

def test_load_env():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 'env_value'}
    del os.environ['APP__KEY']

def test_coerce_int():
    defaults = {'key': 1}
    os.environ['APP__KEY'] = '2'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 2}
    del os.environ['APP__KEY']

def test_coerce_float():
    defaults = {'key': 1.0}
    os.environ['APP__KEY'] = '2.0'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 2.0}
    del os.environ['APP__KEY']

def test_coerce_bool():
    defaults = {'key': True}
    os.environ['APP__KEY'] = 'false'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': False}
    del os.environ['APP__KEY']

def test_missing_default():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='APP__')
    assert 'No default for environment variable' in str(excinfo.value)
    del os.environ['APP__KEY']

def test_unsupported_type():
    defaults = {'key': []}
    os.environ['APP__KEY'] = 'value'
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='APP__')
    assert 'Unsupported type for environment variable' in str(excinfo.value)
    del os.environ['APP__KEY']

